    if (inputValue.trim() === "") return;

    console.log("Input submitted via Enter:", inputValue);
    

    setInputValue(""); 
  };
  
    return (
    <div className="flex-1 flex flex-col items-center justify-center">
      <h1 className="text-4xl font-bold">Hi username, How Can I Help?</h1>
      <form onSubmit={handleSubmit}>
        <input 
          type="text" 
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          className="border border-gray-300 rounded p-2 w-1/2 focus:ring-2 focus:ring-blue-500 outline-none" 
          placeholder="Type something and press Enter..." 
        />
      </form>
    </div>
  );
}

export default Home;
